edits.old:
if here.diseased {
    return;
}
name = here.variety.name;
self.kg[name] = self.kg.get(name, 0.0) + MATURE_KG[name] * age_factor(here.age);

edits.new:
name = here.variety.name;
f = 0.0 if here.diseased else age_factor(here.age);
self.kg[name] = self.kg.get(name, 0.0) + MATURE_KG[name] * f;
